        ("aliyun", "阿里云", ["ECS", "ACK", "SLS", "RDS"]),
        ("mongodb", "MongoDB", ["文档建模", "查询", "聚合"]),
        ("data_basics", "数据系统基础", ["事务与分析", "缓存", "数据治理"]),
        ("openstack", "OpenStack", ["计算", "网络", "存储", "身份"]),
        ("cloud_basics", "云计算基础", ["服务模型", "部署模型", "责任边界"]),
        ("puppet", "Puppet", ["资源模型", "Facter", "Hiera"]),
